```cpp
template<class Type> int BinarySearch(Type a[], const Type& x, int n) // 在  $a[0] < = a[1] < = \ldots < = a[n-1]$  中搜索  $x$  // 找到  $x$  时返回其在数组中的位置，否则返回 -1
int left = 0; int right = n - 1;
while (left <= right) {
    int middle = (left + right) / 2;
    if (x == a[mid]) return middle;
    if (x > a[mid]) left = middle + 1;
    else right = middle - 1;
}
return -1; // 未找到  $x$
```

