template<class Typep, class Typep> 
Typep Knapsack(Typep p[], Typew w[], Typew c, int n, int bestx[]) 
{ // 返回最大价值，bestx返回最优解
    // 初始化
    Typew W = 0; // 装包物品重量
    Typew P = 0; // 装包物品价值
    // 定义依单位重量价值排序的物品数组
    Object *Q = new Object[n];
    for (int i = 1; i <= n; i++) {
        // 单位重量价值数组
        Q[i-1].ID = i;
        Q[i-1].d = 1.0 * p[i] / w[i];
        P += p[i];
        W += w[i];
    }
    if (W <= c) return P; // 所有物品装包
    // 依单位重量价值排序
    Sort(Q, n);
    // 创建类 Knap 的数据成员
    Knap<Typew, Typep> K;
    K.p = new Typep[n+1];
    K.w = new Typep[n+1];
    for (int i = 1; i <= n; i++) {
        K.p[i] = p[Q[i-1].ID];
        K.w[i] = w[Q[i-1].ID];
    }
    K.cp = 0;
    K.cw = 0;
    K.c = c;
    K.n = n;
    // 调用 MaxKapsack 求问题的最优解
    Typew bestp = K.MaxKapsack();
    for (int j = 1; j <= n; j++) 
        bestx[Q[j-1].ID] = K.bestx[j];
    delete[] Q;
    delete[] K.w;
    delete[] K.p;
    delete[] K.bestx;
    return bestp;
