template<class Graph, class Edge> static int cost(Graph &G) {
    int x = 0;
    for (int v = 0; v < G.V(); v++) {
        adjIterator<edge> A(G, v);
        for (Edge * e = A.beg(); !

A.end(); e = A.nxt())
