template<class Type> void Stack<Type Type& x) {
    if(IsFull()) StackFull();
    else stack[++top] = x;
} template<class Type> Type * Stack<Type Type>::Pop(Type& x)
{
    if(IsEmpty()) {StackEmpty(); return 0;} x = stack[top--];
    return &x;
}
```

