class LinkedListStack{ private:lescNode \*stkTop; //将头节点作为栈顶 intstkSize; //栈的长度   
public: LinkedListStack(){ stackTop  $\equiv$  nullptr;stkSize  $= 0$  · } ~LinkedListStack(){ //遍历链表删除节点，释放内存 freeMemoryLinkedList(stckTop); } /\*获取栈的长度\*/ int size(){ returnstkSize;
```

```c
/* 判断栈是否为空 */
bool isEmpty() {
    return size() == 0;
}
/* 入栈 */
void push(int num) {
    ListNode *node = new ListNode(num);
    node->next = stackTop;
    stackTop = node;
   stkSize++;
}
/* 出栈 */
int pop() {
    int num = top();
    ListNode *tmp = stackTop;
    stackTop = stackTop->next;
    //释放内存
    delete tmp;
   stkSize--;
    return num;
}
/* 访问栈顶元素 */
int top() {
    if (isEmpty())
        throw out_of_range("栈为空");
    return stackTop->val;
}
/* 将List转化为Array并返回*/
vector<int> toVector() {
    ListNode *node = stackTop;
    vector<int> res(size());
    for (int i = res.size() - 1; i >= 0; i--) {
        res[i] = node->val;
        node = node->next;
    }
    return res;
}
```

