void siftDown(int i) {  
    while (true) {  
        //判断节点i, l, r中值最大的节点，记为ma  
        int l = left(i), r = right(i), ma = i;  
        if (l < size() && maxHeap[l] > maxHeap[ma])  
            ma = l;  
        if (r < size() && maxHeap[r] > maxHeap[ma])  
            ma = r;  
        //若节点i最大或索引l，r越界，则无须继续堆化，跳出  
        if (ma == i)  
            break;  
        swap(maxHeap[i], maxHeap[ma]);  
        //循环向下堆化  
        i = ma;  
    }  
}
