int binarySearchvector<int> &nums, int target) { // 初始化双闭区间  $[0, n - 1]$ ，即  $i, j$  分别指向数组首元素、尾元素  
int  $i = 0, j =$  nums.size() - 1; // 循环，当搜索区间为空时跳出（当  $i > j$  时为空）  
while  $(i <= j)$  { int  $m = i + (j - i) / 2$ ; // 计算中点索引  $m$   
if ( $nums[m] <$  target) // 此情况说明 target 在区间  $[m + 1, j]$  中  $i = m + 1$ ;  
else if ( $nums[m] >$  target) // 此情况说明 target 在区间  $[i, m - 1]$  中  $j = m - 1$ ;  
else // 找到目标元素，返回其索引  
return  $m$ ;  
}  
// 未找到目标元素，返回 -1  
return -1;
```

时间复杂度为  $O(\log n)$  : 在二分循环中, 区间每轮缩小一半, 因此循环次数为  $\log_2 n$  。

